const config = $('Engine Input').first().json;
const rows = items.map(i => i.json);
const today = $now.toFormat('yyyy-MM-dd');
const thirtyDaysAgo = $now.minus({ days: 30 }).toFormat('yyyy-MM-dd');

const todaysRows = rows.filter(r =>
  r.date === today &&
  r.channel === config.channel &&
  ['approved', 'pending_review', 'published'].includes(r.status)
);

const recentRows = rows.filter(r => r.date >= thirtyDaysAgo);
const recentUrls = new Set(recentRows.map(r => r.article_url).filter(Boolean));
const recentHashes = new Set(rows.map(r => r.content_hash).filter(Boolean));

return [{
  json: {
    ...config,
    today,
    daily_count: todaysRows.length,
    limit_reached: todaysRows.length >= config.daily_limit,
    recent_urls: Array.from(recentUrls),
    recent_hashes: Array.from(recentHashes)
  }
}];

return items.filter(i => String(i.json.active).toUpperCase() === 'TRUE').map(i => ({
  json: { source_name: i.json.source_name, url: i.json.url }
}));

const sourceItems = $('Filter Active Sources').all();
const sourceName = sourceItems[$runIndex] ? sourceItems[$runIndex].json.source_name : 'unknown';

return items.map(i => ({
  json: {
    source_name: sourceName,
    title: i.json.title,
    link: i.json.link,
    contentSnippet: i.json.contentSnippet || i.json.content || '',
    isoDate: i.json.isoDate || i.json.pubDate || ''
  }
}));

const recentUrls = new Set($('Analyze Content Log').first().json.recent_urls || []);
const seen = new Set();
const out = [];
for (const item of items) {
  const url = item.json.link;
  if (!url || recentUrls.has(url) || seen.has(url)) continue;
  seen.add(url);
  out.push(item);
}
return out;

