const candidates = $('Aggregate Candidates').first().json.candidates;
const raw = $json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('DeepSeek relevance response was not valid JSON: ' + raw);
}
const idx = parsed.selected_index;
if (typeof idx !== 'number' || idx < 0 || idx >= candidates.length) {
  throw new Error('DeepSeek returned an out-of-range selected_index: ' + idx);
}
const selected = candidates[idx];
return [{
  json: {
    ...$('Analyze Content Log').first().json,
    article_title: selected.title,
    article_url: selected.link,
    article_snippet: selected.contentSnippet,
    sources_consulted: selected.source_name,
    day_topic: parsed.day_topic || selected.title
  }
}];

