const crypto = require('crypto');
const ctx = $('Parse Relevance Selection').first().json;
const draft = $json.choices[0].message.content.trim();
const hash = crypto.createHash('sha256').update(draft).digest('hex');

const recentHashes = new Set(ctx.recent_hashes || []);
if (recentHashes.has(hash)) {
  throw new Error('Generated draft hash matches a previously logged post - possible near-duplicate content. Aborting this run; rerun manually if this looks like a false positive.');
}

return [{
  json: {
    date: ctx.today,
    profile: ctx.profile,
    channel: ctx.channel,
    sources_consulted: ctx.sources_consulted,
    article_title: ctx.article_title,
    article_url: ctx.article_url,
    draft_content: draft,
    content_hash: hash,
    status: 'pending_review',
    published_at: '',
    telegram_message_id: '',
    day_topic: ctx.day_topic,
    dry_run: ctx.dry_run,
    spreadsheet_id: ctx.spreadsheet_id,
    content_tab: ctx.content_tab
  }
}];

